/*
 * Builds the fast version of Tactics Table.
 *
 *   artifact/tactics-table.source.html  — the page you edit. Compiles its own JSX in the browser (slow to open).
 *   artifact/tactics-table.html         — GENERATED by this script. Same page with the JSX compiled ahead of time,
 *                                         so it opens instantly, plus offline caching. This is the URL players use.
 *
 * Run from the repo root after any change to the source file:
 *   node scripts/build-tactics-table.cjs
 */
const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const root = path.join(__dirname, '..');
const srcPath = path.join(root, 'artifact', 'tactics-table.source.html');
const outPath = path.join(root, 'artifact', 'tactics-table.html');

let html = fs.readFileSync(srcPath, 'utf8');

const open = '<script type="text/babel" data-presets="react">';
const start = html.indexOf(open);
const end = html.indexOf('</script>', start);
if (start < 0 || end < 0) throw new Error('Could not find the text/babel script in the source file.');

const jsx = html.slice(start + open.length, end);
const compiled = esbuild.transformSync(jsx, {
  loader: 'jsx',
  jsx: 'transform',
  jsxFactory: 'React.createElement',
  jsxFragment: 'React.Fragment',
  target: 'es2019',
  minify: true,
  legalComments: 'none',
}).code;
if (compiled.includes('</script')) throw new Error('Compiled code contains "</script" which would end the tag early.');

const swRegister =
  "<script>if('serviceWorker' in navigator && /^https?:$/.test(location.protocol)){window.addEventListener('load',function(){navigator.serviceWorker.register('sw.js').catch(function(){});});}</script>";

html = html.slice(0, start) + '<script>' + compiled + '</script>\n' + swRegister + html.slice(end + '</script>'.length);

// the in-browser compiler is no longer needed
const babelTag = /<script src="https:\/\/cdnjs\.cloudflare\.com\/ajax\/libs\/babel-standalone\/[^"]+"><\/script>\n?/;
if (!babelTag.test(html)) throw new Error('Could not find the babel-standalone script tag.');
html = html.replace(babelTag, '');

html = '<!-- GENERATED FILE. Edit artifact/tactics-table.source.html, then run: node scripts/build-tactics-table.cjs -->\n' + html;
fs.writeFileSync(outPath, html);
console.log('Built', path.relative(root, outPath), '—', (html.length / 1024).toFixed(0) + ' KB (source was ' + (fs.statSync(srcPath).size / 1024).toFixed(0) + ' KB)');
